CREATE OR REPLACE FUNCTION public.check_salon_eligibility(p_salon_id uuid,p_user_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_user_id uuid:=COALESCE(p_user_id,auth.uid()); v_rules public.community_salon_access_rules; v_profile record; v_is_certified boolean; v_age integer; BEGIN IF v_user_id IS NULL THEN RETURN false; END IF; SELECT * INTO v_rules FROM public.community_salon_access_rules WHERE salon_id=p_salon_id; IF NOT FOUND THEN RETURN true; END IF; SELECT country_id,city_id,gender,birth_date INTO v_profile FROM public.user_profiles WHERE user_id=v_user_id; IF NOT FOUND THEN RETURN false; END IF; IF v_rules.countries_enabled AND (v_profile.country_id IS NULL OR NOT (v_profile.country_id=ANY(v_rules.allowed_countries))) THEN RETURN false; END IF; IF v_rules.cities_enabled AND (v_profile.city_id IS NULL OR NOT (v_profile.city_id=ANY(v_rules.allowed_cities))) THEN RETURN false; END IF; IF v_rules.gender_restriction IS NOT NULL AND (v_profile.gender IS NULL OR v_profile.gender<>v_rules.gender_restriction) THEN RETURN false; END IF; IF v_rules.certification_required THEN SELECT EXISTS(SELECT 1 FROM public.user_certifications WHERE user_id=v_user_id AND status='active') INTO v_is_certified; IF NOT COALESCE(v_is_certified,false) THEN RETURN false; END IF; END IF; IF (v_rules.age_min IS NOT NULL OR v_rules.age_max IS NOT NULL) THEN IF v_profile.birth_date IS NULL THEN RETURN false; END IF; v_age:=EXTRACT(YEAR FROM age(v_profile.birth_date)); IF v_rules.age_min IS NOT NULL AND v_age<v_rules.age_min THEN RETURN false; END IF; IF v_rules.age_max IS NOT NULL AND v_age>v_rules.age_max THEN RETURN false; END IF; END IF; RETURN true; END; $$; CREATE OR REPLACE FUNCTION public.review_community_chat_group_request(p_request_id uuid,p_decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_request public.community_salon_join_requests; v_salon public.community_salons; BEGIN IF auth.uid() IS NULL OR p_decision NOT IN ('accepted','rejected') THEN RAISE EXCEPTION 'Requête invalide'; END IF; SELECT * INTO v_request FROM public.community_salon_join_requests WHERE id=p_request_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Demande introuvable'; END IF; SELECT * INTO v_salon FROM public.community_salons WHERE id=v_request.salon_id; IF v_salon.created_by<>auth.uid() AND NOT public.community_can(v_salon.community_id,'can_create_salon') THEN RAISE EXCEPTION 'Action non autorisée'; END IF; IF v_request.status<>'pending' THEN RAISE EXCEPTION 'Cette demande a déjà été traitée'; END IF; IF p_decision='accepted' THEN IF NOT EXISTS(SELECT 1 FROM public.community_members cm WHERE cm.community_id=v_salon.community_id AND cm.user_id=v_request.user_id) OR NOT public.check_salon_eligibility(v_salon.id,v_request.user_id) THEN RAISE EXCEPTION 'Le demandeur ne remplit plus les conditions d’accès'; END IF; INSERT INTO public.community_salon_members(salon_id,user_id,role) VALUES(v_salon.id,v_request.user_id,'member') ON CONFLICT DO NOTHING; END IF; UPDATE public.community_salon_join_requests SET status=p_decision,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=p_request_id; RETURN jsonb_build_object('status',p_decision,'request_id',p_request_id); END; $$; REVOKE ALL ON FUNCTION public.check_salon_eligibility(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.check_salon_eligibility(uuid,uuid) TO authenticated;